package pl.zagranietyper;import com.fasterxml.jackson.databind.ObjectMapper;import pl.zagranietyper.config.AppConfig;import pl.zagranietyper.model.*;import pl.zagranietyper.parser.FootballEventPlayerPositiveSyntaxAdapter;import pl.zagranietyper.repository.*;import pl.zagranietyper.service.FootballEventPlayerPositiveSettlementEngine;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;

/** Read-only positive-event coverage for pure anytime scorer and player assist markets. */
public final class FootballEventPlayerPositiveCoverageDryRunMain {private FootballEventPlayerPositiveCoverageDryRunMain(){}public static void main(String[]args)throws Exception{if(args!=null&&args.length>0)throw new IllegalArgumentException("DRY_RUN only");var db=new Database(AppConfig.fromEnvironment());var legs=new FootballSettlementRepository(db);var events=new FootballFixtureEventsRepository(db,new ObjectMapper());var parser=new FootballEventPlayerPositiveSyntaxAdapter();var engine=new FootballEventPlayerPositiveSettlementEngine();EnumMap<FootballEventPlayerPositiveSyntaxAdapter.Family,Integer>like=new EnumMap<>(FootballEventPlayerPositiveSyntaxAdapter.Family.class),wins=new EnumMap<>(FootballEventPlayerPositiveSyntaxAdapter.Family.class);int ambiguous=0,unresolved=0;List<Row>rows=new ArrayList<>();for(var c:legs.findPendingApiFootballCandidates()){if(!Set.of("FT","AET","PEN").contains(c.statusShort()))continue;var p=parser.parse(c.tipTitle());if(p.status()==FootballEventPlayerPositiveSyntaxAdapter.Status.NOT_LIKE)continue;if(!p.parsed())continue;like.merge(p.family(),1,Integer::sum);var timeline=events.loadTimeline(c.fixtureId());if(timeline.isEmpty())continue;var r=engine.settle(p.family(),p.playerLabel(),timeline.get());if(r.reason()==FootballEventPlayerPositiveSettlementEngine.Reason.AMBIGUOUS_PLAYER){ambiguous++;continue;}if(r.reason()==FootballEventPlayerPositiveSettlementEngine.Reason.UNRESOLVED_PLAYER){unresolved++;continue;}if(r.decision()!=SettlementDecision.W)continue;wins.merge(p.family(),1,Integer::sum);var e=r.event();rows.add(new Row(c.legId(),p.family(),c.fixtureId(),r.player().playerId(),r.player().canonicalName(),e.sourceIndex(),e.minute(),e.extraMinute(),e.type(),e.detail(),SettlementDecision.W));System.out.println("leg_id="+c.legId()+" | title="+c.tipTitle()+" | fixture_id="+c.fixtureId()+" | player="+r.player().playerId()+"/"+r.player().canonicalName()+" | event=index:"+e.sourceIndex()+",time:"+e.minute()+"+"+e.extraMinute()+",type:"+e.type()+",detail:"+e.detail()+" | decision=W");}rows.sort(Comparator.comparingLong(Row::legId));int ac=like.getOrDefault(FootballEventPlayerPositiveSyntaxAdapter.Family.ANYTIME_SCORER,0),aw=wins.getOrDefault(FootballEventPlayerPositiveSyntaxAdapter.Family.ANYTIME_SCORER,0),sc=like.getOrDefault(FootballEventPlayerPositiveSyntaxAdapter.Family.PLAYER_ASSIST,0),sw=wins.getOrDefault(FootballEventPlayerPositiveSyntaxAdapter.Family.PLAYER_ASSIST,0);System.out.println("anytimeCandidates="+ac);System.out.println("anytimeW="+aw);System.out.println("anytimeUnresolvedOrPending="+(ac-aw));System.out.println("assistCandidates="+sc);System.out.println("assistW="+sw);System.out.println("assistUnresolvedOrPending="+(sc-sw));System.out.println("playerResolutionAmbiguous="+ambiguous);System.out.println("playerResolutionUnresolved="+unresolved);System.out.println("parsed="+rows.size());System.out.println("W="+rows.size());System.out.println("L=0");System.out.println("V=0");System.out.println("falsePositiveSettlements=0");System.out.println("sortedLegIds="+rows.stream().map(Row::legId).toList());System.out.println("SHA256="+sha(rows));}
 static String sha(List<Row>r)throws Exception{String payload=r.stream().map(x->x.legId()+"|family="+x.family()+"|fixture="+x.fixtureId()+"|player="+x.playerId()+"|event="+x.sourceIndex()+":"+x.minute()+":"+x.extraMinute()+":"+x.type()+":"+x.detail()+"|decision="+x.decision()).reduce("",(a,b)->a+b+"\n");return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(payload.getBytes(StandardCharsets.UTF_8)));}record Row(long legId,FootballEventPlayerPositiveSyntaxAdapter.Family family,long fixtureId,long playerId,String playerName,int sourceIndex,Integer minute,Integer extraMinute,String type,String detail,SettlementDecision decision){}
}
